<?php
namespace App\Services;
use App\Models\PendaftaranPpdb; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class PpdbService { public function daftar(array $data): PendaftaranPpdb { return DB::transaction(fn()=>PendaftaranPpdb::create($data),3); } public function verifikasi(int $id,int $petugas,string $status,?string $catatan=null):PendaftaranPpdb { $allowed=['diverifikasi','diterima','ditolak','perlu_perbaikan']; if(!in_array($status,$allowed,true)) throw ValidationException::withMessages(['status'=>'Status PPDB tidak valid']); return DB::transaction(function()use($id,$petugas,$status,$catatan){$p=PendaftaranPpdb::query()->lockForUpdate()->findOrFail($id); if(!in_array($p->status_pendaftaran,['menunggu','perlu_perbaikan'],true)) throw ValidationException::withMessages(['status'=>'Pendaftaran telah diputuskan']); $p->update(['status_pendaftaran'=>$status,'id_pengguna_pemeriksa'=>$petugas,'catatan_verifikasi'=>$catatan,'diperiksa_pada'=>now()]); return $p->refresh();},3); } }
